def subtract(a, b):
    # Filter out empty intervals (start >= end)
    a = [interval for interval in a if interval[0] < interval[1]]
    b = [interval for interval in b if interval[0] < interval[1]]

    if not a:
        return []

    if not b:
        return sorted(a)

    # Collect all events (start and end points)
    events = []

    # Add events from a (marked as 'a_start' and 'a_end')
    for start, end in a:
        events.append((start, 'a_start'))
        events.append((end, 'a_end'))

    # Add events from b (marked as 'b_start' and 'b_end')
    for start, end in b:
        events.append((start, 'b_start'))
        events.append((end, 'b_end'))

    # Sort events by position, with careful ordering to handle boundaries
    # For same position: a_end and b_start should come before a_start and b_end
    event_priority = {'a_end': 0, 'b_start': 1, 'a_start': 2, 'b_end': 3}
    events.sort(key=lambda e: (e[0], event_priority[e[1]]))

    result = []
    a_count = 0  # Number of active intervals from a
    b_count = 0  # Number of active intervals from b
    interval_start = None

    for pos, event_type in events:
        # Check if we need to close the current interval
        if interval_start is not None and (a_count == 0 or b_count > 0):
            if interval_start < pos:
                result.append([interval_start, pos])
            interval_start = None

        # Process the event
        if event_type == 'a_start':
            a_count += 1
            if a_count > 0 and b_count == 0 and interval_start is None:
                interval_start = pos
        elif event_type == 'a_end':
            a_count -= 1
        elif event_type == 'b_start':
            b_count += 1
        elif event_type == 'b_end':
            b_count -= 1

        # Check if we need to open a new interval
        if interval_start is None and a_count > 0 and b_count == 0:
            interval_start = pos

    return result

